//! Team-legality data (cargo feature `legality`): learnsets with their
//! sources, event data, evolution chains, species tags and the other fields
//! Showdown's team validator (`sim/team-validator.ts`) reads.
//!
//! Generated by `tools/datagen` from the same Showdown as the battle tables,
//! one [`Legality`] per dex ([`gen9::LEGALITY`], [`champions::LEGALITY`]),
//! indexed by the shared IDs. Like the rest of this crate it only describes
//! data; the validator itself is the `pikapro-validate` crate.
//!
//! The tables are behind a feature because they are large (every learnset
//! of both dexes): only the validator needs them, so the simulator's build
//! does not pay for them.

use crate::{AbilityId, ItemId, MoveId, Nature, SpeciesId};

/// The Pokémon Champions legality tables (generated).
pub mod champions;
/// The Scarlet/Violet legality tables (generated).
pub mod gen9;

/// The legality tables of one dex.
#[derive(Debug)]
pub struct Legality {
    /// The dex's name (`"gen9"`, `"champions"`).
    pub name: &'static str,
    /// By [`SpeciesId`].
    pub species: &'static [SpeciesLegality],
    /// By [`MoveId`].
    pub moves: &'static [MoveLegality],
    /// By [`ItemId`].
    pub items: &'static [ItemLegality],
}

impl Legality {
    /// The species `id`'s data.
    #[inline]
    pub fn species(&self, id: SpeciesId) -> &SpeciesLegality {
        &self.species[id.index()]
    }

    /// The move `id`'s data.
    #[inline]
    pub fn move_(&self, id: MoveId) -> &MoveLegality {
        &self.moves[id.index()]
    }

    /// The item `id`'s data.
    #[inline]
    pub fn item(&self, id: ItemId) -> &ItemLegality {
        &self.items[id.index()]
    }
}

/// Showdown's `evoRegion`.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum EvoRegion {
    /// Evolves into this forme only in Alola.
    Alola,
    /// Evolves into this forme only in Galar.
    Galar,
}

/// Showdown's `battleOnly`: the forme(s) a battle-only forme starts the
/// battle as.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum BattleOnly {
    /// Not a battle-only forme.
    No,
    /// A single out-of-battle forme (Megas, Aegislash-Blade, ...).
    Species(SpeciesId),
    /// Several (Zygarde-Complete, Necrozma-Ultra).
    Several,
}

/// Showdown's species `tags` that validation rules read.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Hash)]
pub struct SpeciesTags(pub u8);

impl SpeciesTags {
    /// `Mythical`.
    pub const MYTHICAL: SpeciesTags = SpeciesTags(1 << 0);
    /// `Restricted Legendary`.
    pub const RESTRICTED_LEGENDARY: SpeciesTags = SpeciesTags(1 << 1);
    /// `Sub-Legendary`.
    pub const SUB_LEGENDARY: SpeciesTags = SpeciesTags(1 << 2);
    /// `Ultra Beast`.
    pub const ULTRA_BEAST: SpeciesTags = SpeciesTags(1 << 3);
    /// `Paradox`.
    pub const PARADOX: SpeciesTags = SpeciesTags(1 << 4);

    /// Whether every tag of `other` is set.
    #[inline]
    pub const fn contains(self, other: SpeciesTags) -> bool {
        self.0 & other.0 == other.0
    }
}

/// A tier of a species on Showdown (`species.tier` and
/// `species.doublesTier`, from its `formats-data`): what the tier tags of
/// the Smogon formats read (`Uber` and `AG` are banned in `[Gen 9] OU`).
/// A name in parentheses is Showdown's own (`(OU)`: in the tier by usage,
/// not ranked). A species without a doubles tier has its singles tier
/// there, so one type holds both.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Tier {
    /// `AG`.
    Ag,
    /// `Uber`.
    Uber,
    /// `(Uber)`.
    UberUnranked,
    /// `OU`.
    Ou,
    /// `(OU)`.
    OuUnranked,
    /// `UUBL`.
    Uubl,
    /// `UU`.
    Uu,
    /// `RUBL`.
    Rubl,
    /// `RU`.
    Ru,
    /// `NUBL`.
    Nubl,
    /// `NU`.
    Nu,
    /// `(NU)`.
    NuUnranked,
    /// `PUBL`.
    Publ,
    /// `PU`.
    Pu,
    /// `(PU)`.
    PuUnranked,
    /// `ZUBL`.
    Zubl,
    /// `ZU`.
    Zu,
    /// `NFE`: not fully evolved.
    Nfe,
    /// `LC`: Little Cup.
    Lc,
    /// `DUber` (doubles).
    DUber,
    /// `(DUber)`.
    DUberUnranked,
    /// `DOU`.
    Dou,
    /// `(DOU)`.
    DouUnranked,
    /// `DBL`.
    Dbl,
    /// `DUU`.
    Duu,
    /// `(DUU)`.
    DuuUnranked,
    /// `Unreleased`.
    Unreleased,
    /// `Illegal`: not in the game.
    Illegal,
    /// `CAP`.
    Cap,
    /// `CAP NFE`.
    CapNfe,
    /// `CAP LC`.
    CapLc,
}

impl Tier {
    /// The tier as Showdown writes it.
    pub const fn name(self) -> &'static str {
        match self {
            Tier::Ag => "AG",
            Tier::Uber => "Uber",
            Tier::UberUnranked => "(Uber)",
            Tier::Ou => "OU",
            Tier::OuUnranked => "(OU)",
            Tier::Uubl => "UUBL",
            Tier::Uu => "UU",
            Tier::Rubl => "RUBL",
            Tier::Ru => "RU",
            Tier::Nubl => "NUBL",
            Tier::Nu => "NU",
            Tier::NuUnranked => "(NU)",
            Tier::Publ => "PUBL",
            Tier::Pu => "PU",
            Tier::PuUnranked => "(PU)",
            Tier::Zubl => "ZUBL",
            Tier::Zu => "ZU",
            Tier::Nfe => "NFE",
            Tier::Lc => "LC",
            Tier::DUber => "DUber",
            Tier::DUberUnranked => "(DUber)",
            Tier::Dou => "DOU",
            Tier::DouUnranked => "(DOU)",
            Tier::Dbl => "DBL",
            Tier::Duu => "DUU",
            Tier::DuuUnranked => "(DUU)",
            Tier::Unreleased => "Unreleased",
            Tier::Illegal => "Illegal",
            Tier::Cap => "CAP",
            Tier::CapNfe => "CAP NFE",
            Tier::CapLc => "CAP LC",
        }
    }
}

/// A species' egg groups, one bit per group ([`EggGroups::NAMES`] order).
/// `Undiscovered` never shares a species with another group.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Hash)]
pub struct EggGroups(pub u16);

impl EggGroups {
    /// The groups' names, in bit order.
    pub const NAMES: [&'static str; 15] = [
        "Monster",
        "Water 1",
        "Bug",
        "Flying",
        "Field",
        "Fairy",
        "Grass",
        "Human-Like",
        "Water 3",
        "Mineral",
        "Amorphous",
        "Water 2",
        "Ditto",
        "Dragon",
        "Undiscovered",
    ];
    /// `Undiscovered`.
    pub const UNDISCOVERED: EggGroups = EggGroups(1 << 14);
    /// `Field`.
    pub const FIELD: EggGroups = EggGroups(1 << 4);

    /// Whether it is in `Undiscovered` (can't breed).
    #[inline]
    pub const fn is_undiscovered(self) -> bool {
        self.0 & Self::UNDISCOVERED.0 != 0
    }

    /// Whether the two share a group.
    #[inline]
    pub const fn intersects(self, other: EggGroups) -> bool {
        self.0 & other.0 != 0
    }

    /// Whether it has no group.
    #[inline]
    pub const fn is_empty(self) -> bool {
        self.0 == 0
    }
}

/// Showdown's Pokémon GO `encounters` for a species.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Hash)]
pub struct GoSources(pub u16);

impl GoSources {
    /// `wild`.
    pub const WILD: GoSources = GoSources(1 << 0);
    /// `egg`.
    pub const EGG: GoSources = GoSources(1 << 1);
    /// `12kmegg`.
    pub const EGG_12KM: GoSources = GoSources(1 << 2);
    /// `raid`.
    pub const RAID: GoSources = GoSources(1 << 3);
    /// `research`.
    pub const RESEARCH: GoSources = GoSources(1 << 4);
    /// `giovanni`.
    pub const GIOVANNI: GoSources = GoSources(1 << 5);
    /// `noTrade`.
    pub const NO_TRADE: GoSources = GoSources(1 << 6);
    /// `specialTrade`.
    pub const SPECIAL_TRADE: GoSources = GoSources(1 << 7);
    /// `noShiny`.
    pub const NO_SHINY: GoSources = GoSources(1 << 8);

    /// Whether every source of `other` is set.
    #[inline]
    pub const fn contains(self, other: GoSources) -> bool {
        self.0 & other.0 == other.0
    }
}

/// An event's gender requirement.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum EventGender {
    /// Male only.
    Male,
    /// Female only.
    Female,
}

/// An event's shininess (Showdown's `shiny`: `true`, `1` or absent).
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum EventShiny {
    /// Absent: never shiny.
    Never,
    /// `true`: always shiny.
    Always,
    /// `1`: may be shiny.
    Maybe,
}

/// One entry of a species' `eventData`, with the fields the validator
/// reads (`validateEvent`). Showdown's `abilities` only matter in Gen 5 and
/// earlier and `moves` / `pokeball` never; they are left out.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct EventInfo {
    /// The event's generation.
    pub generation: u8,
    /// 0: no level requirement.
    pub level: u8,
    /// Its shininess.
    pub shiny: EventShiny,
    /// Its fixed gender.
    pub gender: Option<EventGender>,
    /// Its fixed nature.
    pub nature: Option<Nature>,
    /// Fixed IVs, hp to spe; [`EventInfo::NO_IV`] where the event has none.
    pub ivs: Option<[u8; 6]>,
    /// Showdown's `perfectIVs`: how many IVs are 31.
    pub perfect_ivs: u8,
    /// Showdown's `isHidden`: it has its hidden ability.
    pub is_hidden: bool,
    /// Showdown's `emeraldEventEgg`.
    pub emerald_event_egg: bool,
}

impl EventInfo {
    /// An IV the event does not fix.
    pub const NO_IV: u8 = u8::MAX;

    /// An event of `generation` with no requirements (the generated rows
    /// start from it).
    pub const fn blank(generation: u8) -> EventInfo {
        EventInfo {
            generation,
            level: 0,
            shiny: EventShiny::Never,
            gender: None,
            nature: None,
            ivs: None,
            perfect_ivs: 0,
            is_hidden: false,
            emerald_event_egg: false,
        }
    }
}

/// How a move is learned (the letter of a Showdown learnset source).
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
#[repr(u8)]
pub enum SourceKind {
    /// `L`: level-up (the value is the level).
    LevelUp = 0,
    /// `M`: TM/HM.
    Machine = 1,
    /// `T`: tutor.
    Tutor = 2,
    /// `R`: restricted (a signature move).
    Restricted = 3,
    /// `E`: egg move.
    Egg = 4,
    /// `S`: event (the value is the index into `eventData`).
    Event = 5,
    /// `D`: Dream World.
    DreamWorld = 6,
    /// `V`: Virtual Console or Let's Go transfer.
    Transfer = 7,
}

impl SourceKind {
    /// Showdown's letter.
    pub const fn letter(self) -> char {
        match self {
            SourceKind::LevelUp => 'L',
            SourceKind::Machine => 'M',
            SourceKind::Tutor => 'T',
            SourceKind::Restricted => 'R',
            SourceKind::Egg => 'E',
            SourceKind::Event => 'S',
            SourceKind::DreamWorld => 'D',
            SourceKind::Transfer => 'V',
        }
    }
}

/// A learnset source such as `9L32` or `8S1`, packed as
/// `gen << 12 | kind << 9 | value`.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub struct LearnSource(pub u16);

impl LearnSource {
    /// The generation.
    #[inline]
    pub const fn generation(self) -> u8 {
        (self.0 >> 12) as u8
    }

    /// How the move is learned.
    #[inline]
    pub const fn kind(self) -> SourceKind {
        match (self.0 >> 9) & 7 {
            0 => SourceKind::LevelUp,
            1 => SourceKind::Machine,
            2 => SourceKind::Tutor,
            3 => SourceKind::Restricted,
            4 => SourceKind::Egg,
            5 => SourceKind::Event,
            6 => SourceKind::DreamWorld,
            _ => SourceKind::Transfer,
        }
    }

    /// The level of an `L` source, the event index of an `S` source.
    #[inline]
    pub const fn value(self) -> u16 {
        self.0 & 0x1ff
    }
}

/// One move of a learnset.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct LearnEntry {
    /// The move.
    pub move_: MoveId,
    /// Showdown's sources ([`LearnSource`]s), newest first, as in its data.
    pub sources: &'static [u16],
    /// The lowest level at which the move can be relearned from a
    /// Brilliant Diamond / Shining Pearl or Legends: Arceus learnset
    /// through HOME (`getExternalLearnsetData`), if any. Only recorded for
    /// moves with a Gen 9 non-event source, the only case Showdown looks.
    pub home_level: Option<u8>,
}

/// Iterates over a packed learnset: `[move, count | home << 8, sources...]*`
/// where `home` is 0 for none, else the relearn level + 1.
#[derive(Clone, Debug)]
pub struct LearnsetIter {
    data: &'static [u16],
}

impl Iterator for LearnsetIter {
    type Item = LearnEntry;

    fn next(&mut self) -> Option<LearnEntry> {
        let [move_, header, rest @ ..] = self.data else { return None };
        let count = (header & 0xff) as usize;
        let home = header >> 8;
        let (sources, rest) = rest.split_at(count);
        self.data = rest;
        Some(LearnEntry {
            move_: MoveId(*move_),
            sources,
            home_level: if home == 0 { None } else { Some((home - 1) as u8) },
        })
    }
}

/// A species' learnset (Showdown's `learnset` object).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Learnset(pub &'static [u16]);

impl Learnset {
    /// Its entries.
    pub fn iter(self) -> LearnsetIter {
        LearnsetIter { data: self.0 }
    }

    /// The entry for `move_`, if the species learns it.
    pub fn get(self, move_: MoveId) -> Option<LearnEntry> {
        self.iter().find(|e| e.move_ == move_)
    }
}

/// What the validator needs to know about a species beyond
/// [`SpeciesData`](crate::SpeciesData).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct SpeciesLegality {
    /// The generation it was introduced in (Showdown's `gen`).
    pub generation: u8,
    /// Showdown's `prevo`.
    pub prevo: Option<SpeciesId>,
    /// The first of `evos`.
    pub first_evo: Option<SpeciesId>,
    /// 0: none.
    pub evo_level: u8,
    /// `evoMove` of an `evoType: 'levelMove'` evolution.
    pub evo_move: Option<MoveId>,
    /// Showdown's `evoRegion`.
    pub evo_region: Option<EvoRegion>,
    /// Showdown's `changesFrom`: the forme this one changes from.
    pub changes_from: Option<SpeciesId>,
    /// Showdown's `baseForme` (`"Normal"` for Arceus), empty if none.
    pub base_forme: &'static str,
    /// Showdown's `battleOnly`.
    pub battle_only: BattleOnly,
    /// Showdown's `requiredAbility`.
    pub required_ability: Option<AbilityId>,
    /// Showdown's `requiredMove`.
    pub required_move: Option<MoveId>,
    /// Showdown's singular `requiredItem` (messages use it).
    pub required_item: Option<ItemId>,
    /// Showdown's `tags`.
    pub tags: SpeciesTags,
    /// Showdown's `tier`.
    pub tier: Tier,
    /// Showdown's `doublesTier` (its singles tier where it has none).
    pub doubles_tier: Tier,
    /// Showdown's `eggGroups`.
    pub egg_groups: EggGroups,
    /// Showdown's `canHatch`.
    pub can_hatch: bool,
    /// Showdown's `mother` (Nidoran♂, Volbeat, Indeedee).
    pub mother: Option<SpeciesId>,
    /// `None`: no `learnset` in its learnset data.
    pub learnset: Option<Learnset>,
    /// Showdown's `eventData`.
    pub events: &'static [EventInfo],
    /// Showdown's `eventOnly`.
    pub event_only: bool,
    /// Pokémon GO encounters, if it has GO data.
    pub go: Option<GoSources>,
    /// `LGPERestrictiveMoves` (Mew, Mewtwo): moves and their level, in
    /// Showdown's order.
    pub lgpe_restrictive_moves: &'static [(MoveId, u8)],
}

/// What the validator needs to know about a move beyond
/// [`MoveData`](crate::MoveData).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct MoveLegality {
    /// Showdown's `move.id`: the learnset key (`Hidden Power` for every
    /// `Hidden Power <Type>`).
    pub id: MoveId,
    /// The generation it was introduced in (Showdown's `gen`).
    pub generation: u8,
}

/// What the validator needs to know about an item beyond
/// [`ItemData`](crate::ItemData).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct ItemLegality {
    /// Showdown's `forcedForme` (Plates, masks, Origin items).
    pub forced_forme: Option<SpeciesId>,
}
